'use strict';
const D=window.PLANNER_DATA,R=window.REPLAY_ROUTES,$=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
const bound=(key,fallback,max)=>{const n=Number(params.get(key));return params.has(key)&&Number.isInteger(n)&&n>=1&&n<=max?n:fallback;};
const thresholds={delay:bound('delay',5,120),queue:bound('queue',30,1000)};
let time=27900,playing=false,dated=null,critical=[],scenes=[],loadId=0,lastFrame=0,lastDraw=0;
const clock=t=>{t=Math.floor(t);return [Math.floor(t/3600),Math.floor(t%3600/60),t%60].map(n=>String(n).padStart(2,'0')).join(':');};
const dateLabel=d=>new Date(d+'T12:00:00+08:00').toLocaleDateString('en-SG',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Singapore'});
function pause(){playing=false;$('play').textContent='▶ Play';$('play').setAttribute('aria-pressed','false');$('play').setAttribute('aria-label','Play replay');}
function links(){const query=new URLSearchParams({date:$('replay-date').value,...thresholds});for(const id of ['priorities-link','mobile-back','footer-back'])$(id).href='index.html?'+query;const current=new URL(location.href);current.search=query.toString();history.replaceState(null,'',current);}
async function loadDate(){pause();const token=++loadId,date=$('replay-date').value;dated=null;scenes=[];$('service-scenes').innerHTML='';$('replay-status').textContent='Loading dated stop-call records…';links();critical=PlannerRules.critical(D.services[date],thresholds).sort((a,b)=>b.queue-a.queue);$('critical-summary').textContent=critical.length+' critical services · '+dateLabel(date);$('threshold-summary').textContent='Flags: ≥ '+thresholds.delay+' min delay · ≥ '+thresholds.queue+' passengers';
 try {const result=await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='replay-data/'+date+'.js';script.onload=()=>{resolve(window.REPLAY_DATE);script.remove();};script.onerror=()=>{script.remove();reject(new Error('The dated replay data could not be opened. Keep the replay-data folder beside this page.'));};document.head.append(script);});if(token!==loadId)return;if(result.date!==date)throw Error('Replay date mismatch');dated=result.routes;$('replay-status').textContent='';$('replay-status').className='';$('service-filter').innerHTML='<option value="all">All critical services</option>'+critical.map(s=>`<option value="${esc(s.service)}">Service ${esc(s.service)}</option>`).join('');$('play').disabled=!critical.length;buildScenes();buildRenders();update();}catch(e){if(token===loadId){$('replay-status').className='replay-error';$('replay-status').textContent=e.message;$('play').disabled=true;}}}
function buildScenes(){scenes=[];const selected=$('service-filter').value,shown=critical.filter(s=>selected==='all'||s.service===selected);if(!shown.length){$('service-scenes').innerHTML='<section class="panel scene-empty">No services are critical under the selected date and thresholds. Return to service priorities to review or adjust the triggers.</section>';return;}
 $('service-scenes').innerHTML=shown.map(s=>{const routes=Object.entries(R).filter(([,r])=>r.service===s.service);return `<section class="panel service-scene"><div class="panel-heading"><div><h2><span class="service-code">${esc(s.service)}</span>Service ${esc(s.service)} <span class="badge critical">Critical</span></h2><p>${esc(s.name)}</p></div><div class="scene-summary">${s.queue} passengers · morning peak queue<br>${s.delays[0]?.minutes.toFixed(1)||0} min · maximum departure delay</div></div><div class="direction-grid">${routes.map(([id,r],index)=>`<section class="direction-panel"><div class="direction-heading"><div>${r.loop?'Loop route':'Direction '+esc(r.direction)}<small>${esc(r.stops[0].name)} → ${esc(r.stops[r.stops.length-1].name)}</small></div><span class="direction-stats" id="stats-${id}"></span></div><canvas id="map-${id}" class="route-canvas" tabindex="0" role="img" aria-label="Service ${esc(s.service)} ${r.loop?'loop':'direction '+esc(r.direction)} bus positions and stop queues"></canvas><div class="bus-list" id="buses-${id}"></div><details><summary>Queues at all ${r.stops.length-1} boarding-stop positions</summary><div class="stop-table"><table><thead><tr><th>Stop</th><th>Queue after boarding</th><th>Observed at</th><th>Age</th></tr></thead><tbody id="stops-${id}"></tbody></table></div></details></section>`).join('')}</div></section>`;}).join('');
 for(const s of shown)for(const [id,r]of Object.entries(R).filter(([,r])=>r.service===s.service)){const scene={id,route:r,canvas:$('map-'+id),color:r.direction==='2'?'#4c6cab':'#34745b',points:[]};scenes.push(scene);scene.canvas.addEventListener('click',e=>{const rect=scene.canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;const p=scene.points.map(p=>({...p,distance:Math.hypot(p.x-x,p.y-y)})).sort((a,b)=>a.distance-b.distance)[0];if(p&&p.distance<25)showStop(id,p.stop.order);});}
 $('service-scenes').querySelectorAll('details').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)update();}));
}
function drawScene(scene){const {route:r,id,canvas,color}=scene,rect=canvas.getBoundingClientRect(),width=rect.width,height=rect.height,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(width*dpr)||canvas.height!==Math.round(height*dpr)){canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);}const ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);
 const lons=r.stops.map(s=>s.lon),lats=r.stops.map(s=>s.lat),minLon=Math.min(...lons),maxLon=Math.max(...lons),minLat=Math.min(...lats),maxLat=Math.max(...lats),ratio=Math.cos((minLat+maxLat)/2*Math.PI/180),geoW=(maxLon-minLon)*ratio,geoH=maxLat-minLat,scale=Math.min((width-110)/(geoW||.001),(height-110)/(geoH||.001)),offsetX=(width-geoW*scale)/2,offsetY=(height-geoH*scale)/2;
 const xy=p=>({x:offsetX+(p.lon-minLon)*ratio*scale,y:height-offsetY-(p.lat-minLat)*scale});ctx.strokeStyle='#e4ecdc';ctx.lineWidth=1;for(let x=25;x<width;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,height);ctx.stroke();}for(let y=20;y<height;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(width,y);ctx.stroke();}ctx.font='12px Segoe UI';ctx.fillStyle='#8e9e80';ctx.fillText('N ↑',width-40,23);ctx.fillText('Stop numbers follow the route sequence',14,height-12);
 const points=r.stops.map(stop=>({...xy(stop),stop}));scene.points=points;ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();
 let affected=0,observed=0;for(const p of points){const q=p.stop.final?null:ReplayEngine.latestQueue(dated[id]?.queues[p.stop.order]||[],time),stale=q&&time-q.time>600;if(q){observed++;if(q.people>0)affected++;}ctx.beginPath();ctx.arc(p.x,p.y,p.stop.final?5:3.5,0,Math.PI*2);ctx.fillStyle=q?.people>=thresholds.queue?'#d77d48':q?.people>0?'#a7be69':color;ctx.fill();
   if(q&&q.people>0){const dx=p.stop.order%2?11:-11,dy=p.stop.order%3===0?14:-12,bx=p.x+dx,by=p.y+dy;ctx.globalAlpha=stale?.48:1;ctx.fillStyle=q.people>=thresholds.queue?'#b75b35':'#526f3b';ctx.font='600 12px Segoe UI';const tw=ctx.measureText(q.people).width;ctx.fillRect(bx-tw/2-4,by-11,tw+8,16);ctx.fillStyle='white';ctx.fillText(q.people,bx-tw/2,by+1);ctx.globalAlpha=1;}else if(p.stop.order===1||p.stop.final||p.stop.order%5===0){ctx.font='12px Segoe UI';ctx.fillStyle='#6e8461';ctx.fillText(p.stop.order,p.x+6,p.y+13);}}
 const buses=[];for(const trip of dated[id]?.trips||[]){const position=ReplayEngine.busPosition(trip,r.stops,time);if(!position)continue;buses.push({trip,position});const p=xy(position);ctx.fillStyle=color;ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.fillRect(p.x-7,p.y-6,14,12);ctx.strokeRect(p.x-7,p.y-6,14,12);ctx.font='600 12px Segoe UI';const label=trip.vehicle.replace('NW-','');ctx.fillStyle='#294d37';ctx.fillText(label,p.x+10,p.y+5);}
 $('stats-'+id).innerHTML=buses.length+' buses<br>'+affected+' / '+observed+' observed stops with queue';$('buses-'+id).textContent=buses.length?buses.map(b=>b.trip.vehicle+(b.position.dwelling?' at stop '+b.position.order:' between stops '+b.position.order+'–'+b.position.next)).join(' · '):'No bus in the recorded route window at this time.';
 canvas.setAttribute('aria-label',`Service ${r.service}, ${r.loop?'loop':'direction '+r.direction}, ${clock(time)}: ${buses.length} buses, ${affected} of ${observed} observed boarding-stop positions have remaining queues. Open the stop table for all observations.`);
 const body=$('stops-'+id);if(body.closest('details').open||!body.childElementCount)body.innerHTML=r.stops.filter(s=>!s.final).map(s=>{const q=ReplayEngine.latestQueue(dated[id]?.queues[s.order]||[],time);return `<tr><td><button data-route="${esc(id)}" data-order="${s.order}">${s.order}. ${esc(s.name)}<span class="units">${esc(s.id)}</span></button></td><td>${q?q.people:'—'}</td><td>${q?clock(q.time):'Not observed'}</td><td class="${q&&time-q.time>600?'stale':''}">${q?Math.floor((time-q.time)/60)+' min':'—'}</td></tr>`;}).join('');
}
function update(){if(!dated)return;$('replay-clock').textContent=clock(time)+' SGT';$('timeline').value=Math.floor(time);$('timeline').setAttribute('aria-valuetext',clock(time)+' Singapore time');for(const scene of scenes)drawScene(scene);}
function showStop(id,order){const s=R[id].stops[order-1],q=s.final?null:ReplayEngine.latestQueue(dated[id]?.queues[order]||[],time);$('stop-content').innerHTML=`<h2 class="dialog-title">${esc(s.name)}</h2><p class="dialog-subtitle">Service ${esc(R[id].service)} · ${R[id].loop?'loop':'direction '+esc(R[id].direction)} · position ${order} · stop ${esc(s.id)}</p><div class="dialog-metrics"><div><strong>${s.final?'—':q?q.people:'—'}</strong>Queue after boarding</div><div><strong>${q?clock(q.time):'—'}</strong>Last boarding observation · SGT</div></div><p class="dialog-subtitle">${s.final?'This final terminal is alighting-only for this trip. No boarding queue is represented.':q?'Recorded '+Math.floor((time-q.time)/60)+' minutes before replay time. Queue changes only at recorded boarding cutoffs; later passenger arrivals are not included in this last observed count.':'No boarding cutoff is recorded yet at this replay time. Missing observations are not treated as zero.'}</p>${q?'<p class="dialog-subtitle">Trip '+esc(q.trip)+'</p>':''}`;$('stop-detail').showModal();}
function buildRenders(){const available=critical.filter(s=>['132','159'].includes(s.service)&&$('replay-date').value==='2026-10-07');$('blender-renders').innerHTML=available.length?'<div class="blender-grid">'+available.map(s=>`<div class="blender-card"><h3>Service ${esc(s.service)} · both directions</h3><video controls preload="metadata" poster="animations/service-${s.service}-2026-10-07-preview.png" aria-label="Blender animation of service ${esc(s.service)} on 7 October"><source src="animations/service-${s.service}-2026-10-07.mp4" type="video/mp4"></video><a href="animations/service-${s.service}-2026-10-07.blend" download>Download Blender scene</a></div>`).join('')+'</div>':'<p class="blender-note">Use the interactive replay above for this selection. Export its data to create a matching Blender render.</p>';}
$('replay-date').innerHTML=D.dates.map(d=>`<option value="${d}">${dateLabel(d)}</option>`).join('');$('replay-date').value=D.dates.includes(params.get('date'))?params.get('date'):'2026-10-07';
$('replay-date').addEventListener('change',loadDate);$('service-filter').addEventListener('change',()=>{buildScenes();update();});$('play').addEventListener('click',()=>{if(playing){pause();return;}if(time>=43200)time=21600;playing=true;lastFrame=performance.now();$('play').textContent='Ⅱ Pause';$('play').setAttribute('aria-pressed','true');$('play').setAttribute('aria-label','Pause replay');});$('timeline').addEventListener('input',()=>{pause();time=Number($('timeline').value);update();});$('reset').addEventListener('click',()=>{pause();time=21600;update();});$('service-scenes').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b)showStop(b.dataset.route,Number(b.dataset.order));});$('close-stop').addEventListener('click',()=>$('stop-detail').close());
$('download-config').addEventListener('click',()=>{if(!dated)return;const ids=Object.keys(R).filter(id=>critical.some(s=>s.service===R[id].service));const payload={routes:Object.fromEntries(ids.map(id=>[id,R[id]])),dates:{[$('replay-date').value]:Object.fromEntries(ids.map(id=>[id,dated[id]]))},default:{date:$('replay-date').value,services:critical.map(s=>s.service),start:21600,end:43200}};const url=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='replay-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
window.addEventListener('resize',update);function frame(now){if(playing&&dated){time=Math.min(43200,time+Math.min((now-lastFrame)/1000,.2)*Number($('speed').value));if(now-lastDraw>50){update();lastDraw=now;}if(time>=43200)pause();}lastFrame=now;requestAnimationFrame(frame);}requestAnimationFrame(frame);loadDate();
